  "inlineSchema": "datasource db {\n  provider = \"postgresql\"\n  url      = env(\"COURSE_DATABASE_URL\")\n}\n\ngenerator client {\n  provider      = \"prisma-client-js\"\n  output        = \"../src/generated/client\"\n  binaryTargets = [\"native\", \"debian-openssl-3.0.x\", \"linux-musl-openssl-3.0.x\"]\n}\n\nenum Role {\n  STUDENT\n  INSTRUCTOR\n  MODERATOR\n  ADMIN\n}\n\nenum Level {\n  BEGINNER\n  INTERMEDIATE\n  ADVANCED\n}\n\nenum LessonType {\n  ARTICLE\n  VIDEO\n  QUIZ\n  EXERCISE\n}\n\n/// Read-model of the auth-service user. Kept in sync from user.* events and refreshed from the\n/// verified token on each request; this service never stores credentials.\nmodel User {\n  id           String   @id\n  email        String   @unique\n  name         String\n  avatar       String?\n  role         Role     @default(STUDENT)\n  bio          String?\n  location     String?\n  skills       String[]\n  githubUrl    String?\n  linkedinUrl  String?\n  portfolioUrl String?\n  isVerified   Boolean  @default(false)\n  createdAt    DateTime @default(now())\n  updatedAt    DateTime @updatedAt\n\n  coursesTaught Course[]\n  enrollments   Enrollment[]\n  progress      LessonProgress[]\n  quizAttempts  QuizAttempt[]\n  discussions   Discussion[]\n  answers       Answer[]\n  answerVotes   AnswerVote[]\n  reviews       Review[]\n  certificates  Certificate[]\n\n  @@map(\"users\")\n}\n\nmodel Course {\n  id           Int      @id @default(autoincrement())\n  title        String\n  description  String\n  category     String   @default(\"General\")\n  level        Level    @default(BEGINNER)\n  price        Decimal  @default(0) @db.Decimal(10, 2)\n  published    Boolean  @default(false)\n  thumbnailUrl String?\n  instructorId String\n  createdAt    DateTime @default(now())\n  updatedAt    DateTime @updatedAt\n\n  instructor   User          @relation(fields: [instructorId], references: [id], onDelete: Cascade)\n  modules      Module[]\n  enrollments  Enrollment[]\n  discussions  Discussion[]\n  reviews      Review[]\n  certificates Certificate[]\n\n  @@index([instructorId])\n  @@index([published, category])\n  @@map(\"courses\")\n}\n\nmodel Module {\n  id       Int    @id @default(autoincrement())\n  courseId Int\n  title    String\n  position Int    @default(0)\n\n  course  Course   @relation(fields: [courseId], references: [id], onDelete: Cascade)\n  lessons Lesson[]\n\n  @@index([courseId, position])\n  @@map(\"modules\")\n}\n\nmodel Lesson {\n  id          Int        @id @default(autoincrement())\n  moduleId    Int\n  title       String\n  type        LessonType @default(ARTICLE)\n  content     String     @default(\"\") // Markdown body (articles / exercise instructions)\n  videoUrl    String?\n  durationMin Int        @default(5)\n  position    Int        @default(0)\n\n  module      Module           @relation(fields: [moduleId], references: [id], onDelete: Cascade)\n  questions   QuizQuestion[]\n  progress    LessonProgress[]\n  attempts    QuizAttempt[]\n  discussions Discussion[]\n\n  @@index([moduleId, position])\n  @@map(\"lessons\")\n}\n\nmodel QuizQuestion {\n  id            Int      @id @default(autoincrement())\n  lessonId      Int\n  position      Int      @default(0)\n  question      String\n  options       String[]\n  correctAnswer Int\n  explanation   String?\n\n  lesson Lesson @relation(fields: [lessonId], references: [id], onDelete: Cascade)\n\n  @@index([lessonId, position])\n  @@map(\"quiz_questions\")\n}\n\nmodel Enrollment {\n  id           Int       @id @default(autoincrement())\n  userId       String\n  courseId     Int\n  enrolledAt   DateTime  @default(now())\n  lastAccessAt DateTime  @default(now())\n  completedAt  DateTime?\n\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n  course Course @relation(fields: [courseId], references: [id], onDelete: Cascade)\n\n  @@unique([userId, courseId])\n  @@index([courseId])\n  @@map(\"enrollments\")\n}\n\nmodel LessonProgress {\n  id          Int      @id @default(autoincrement())\n  userId      String\n  lessonId    Int\n  completedAt DateTime @default(now())\n\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n  lesson Lesson @relation(fields: [lessonId], references: [id], onDelete: Cascade)\n\n  @@unique([userId, lessonId])\n  @@index([userId, completedAt])\n  @@map(\"lesson_progress\")\n}\n\nmodel QuizAttempt {\n  id             Int      @id @default(autoincrement())\n  userId         String\n  lessonId       Int\n  score          Int // percentage 0-100\n  passed         Boolean\n  totalQuestions Int\n  correctAnswers Int\n  submittedAt    DateTime @default(now())\n\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n  lesson Lesson @relation(fields: [lessonId], references: [id], onDelete: Cascade)\n\n  @@index([userId, lessonId])\n  @@map(\"quiz_attempts\")\n}\n\nmodel Discussion {\n  id        Int      @id @default(autoincrement())\n  courseId  Int\n  lessonId  Int?\n  userId    String\n  title     String\n  content   String\n  createdAt DateTime @default(now())\n\n  course  Course   @relation(fields: [courseId], references: [id], onDelete: Cascade)\n  lesson  Lesson?  @relation(fields: [lessonId], references: [id], onDelete: SetNull)\n  user    User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  answers Answer[]\n\n  @@index([courseId, createdAt])\n  @@map(\"discussions\")\n}\n\nmodel Answer {\n  id           Int      @id @default(autoincrement())\n  discussionId Int\n  userId       String\n  content      String\n  accepted     Boolean  @default(false)\n  createdAt    DateTime @default(now())\n\n  discussion Discussion   @relation(fields: [discussionId], references: [id], onDelete: Cascade)\n  user       User         @relation(fields: [userId], references: [id], onDelete: Cascade)\n  votes      AnswerVote[]\n\n  @@index([discussionId])\n  @@map(\"answers\")\n}\n\n// One vote per user per answer.\nmodel AnswerVote {\n  userId   String\n  answerId Int\n\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n  answer Answer @relation(fields: [answerId], references: [id], onDelete: Cascade)\n\n  @@id([userId, answerId])\n  @@map(\"answer_votes\")\n}\n\nmodel Review {\n  id        Int      @id @default(autoincrement())\n  userId    String\n  courseId  Int\n  rating    Int // 1-5\n  comment   String   @default(\"\")\n  createdAt DateTime @default(now())\n\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n  course Course @relation(fields: [courseId], references: [id], onDelete: Cascade)\n\n  @@unique([userId, courseId])\n  @@index([courseId])\n  @@map(\"reviews\")\n}\n\nmodel Certificate {\n  id       String   @id @default(uuid()) // public verification code\n  userId   String\n  courseId Int\n  issuedAt DateTime @default(now())\n\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n  course Course @relation(fields: [courseId], references: [id], onDelete: Cascade)\n\n  @@unique([userId, courseId])\n  @@map(\"certificates\")\n}\n\n/// One row per paid order, written by the payment.succeeded consumer. Powers instructor revenue\n/// without this service reading the payment-service database. orderId makes the consumer idempotent.\nmodel CoursePayment {\n  id       Int      @id @default(autoincrement())\n  orderId  String   @unique\n  userId   String\n  courseId Int\n  amount   Decimal  @db.Decimal(10, 2)\n  paidAt   DateTime @default(now())\n\n  @@index([courseId])\n  @@map(\"course_payments\")\n}\n",
